tool.parameters:
{
  "type": "object",
  "properties": {
    "origin": {
      "type": "string",
      "description": "IATA-код города или аэропорта отправления, например MOW. Уточни неоднозначный город."
    },
    "destination": {
      "type": "string",
      "description": "IATA-код города или аэропорта назначения, например LED."
    },
    "departure_at": {
      "type": "string",
      "description": "Дата вылета YYYY-MM-DD либо месяц YYYY-MM. Уточни год, если он неизвестен."
    },
    "return_at": {
      "type": "string",
      "description": "Дата возвращения YYYY-MM-DD либо YYYY-MM. Для перелёта в одну сторону передай пустую строку."
    },
    "one_way": {
      "type": "boolean",
      "description": "true для перелёта в одну сторону, false для туда-обратно. При false заполни return_at."
    },
    "direct": {
      "type": "boolean",
      "description": "true для прямых рейсов, false допускает пересадки."
    },
    "currency": {
      "type": "string",
      "description": "Код валюты цены, например rub, usd или eur. Согласуй с пользователем."
    }
  },
  "required": [
    "origin",
    "destination",
    "departure_at",
    "return_at",
    "one_way",
    "direct",
    "currency"
  ],
  "additionalProperties": false
}
